-    scopeTracker,
-  })
-
-  scopeTracker.freeze()
-
-  walk(node, {
-    scopeTracker,
-    enter (node, parent) {
-      if (node.type === 'Identifier' && isIdentifierUndeclared(node, parent)) {
-        undeclaredIdentifiers.add(node.name)
-      }
-    },
-  })
-
-  return Array.from(undeclaredIdentifiers)
-}

