+      : resolve(nuxt.options.srcDir, pattern)
+    let shouldAdd = true
+    for (const w of [...pathsToWatch]) {
+      if (w.startsWith(path)) {
+        pathsToWatch.delete(w)
+      }
+      if (path.startsWith(w)) {
+        shouldAdd = false
+      }
+    }
+    if (shouldAdd) {
+      pathsToWatch.add(path)
+    }
+  }
+  return pathsToWatch
+}

