+import { validate, isJS, onEmit } from './util'
+
+export default class VueSSRServerPlugin {
+  constructor(options = {}) {
+    this.options = Object.assign({
+      filename: null
+    }, options)
+  }
+
+  apply(compiler) {
+    validate(compiler)
+
+    onEmit(compiler, 'vue-server-plugin', (compilation, cb) => {
+      const stats = compilation.getStats().toJson()
+      const [entryName] = Object.keys(stats.entrypoints)
+      const entryInfo = stats.entrypoints[entryName]
+
+      if (!entryInfo) {
+        // #5553
+        return cb()
+      }
+
+      const entryAssets = entryInfo.assets.filter(isJS)
+
+      if (entryAssets.length > 1) {
+        throw new Error(
+          `Server-side bundle should have one single entry file. ` +
+          `Avoid using CommonsChunkPlugin in the server config.`
+        )
+      }
+
+      const [entry] = entryAssets
+      if (!entry || typeof entry !== 'string') {
+        throw new Error(
+          `Entry "${entryName}" not found. Did you specify the correct entry option?`
+        )
+      }
+
+      const bundle = {
+        entry,
+        files: {},
+        maps: {}
+      }
+
+      stats.assets.forEach((asset) => {
+        if (isJS(asset.name)) {
+          bundle.files[asset.name] = asset.name
+        } else if (asset.name.match(/\.js\.map$/)) {
+          bundle.maps[asset.name.replace(/\.map$/, '')] = asset.name
+        } else {
+          // Do not emit non-js assets for server
+          delete compilation.assets[asset.name]
+        }
+      })
+
+      const src = JSON.stringify(bundle, null, 2)
+
+      compilation.assets[this.options.filename] = {
+        source: () => src,
+        size: () => src.length
+      }
+
+      cb()
+    })
+  }
+}

