+    // If not redirected
+    if (!nextCalled) {
+      <% if (loading) { %>
+      if (this.$loading.finish && !this.$loading.manual) {
+        this.$loading.finish()
+      }
+      <% } %>
+      next()
+    }
+
+  } catch (err) {
