+}
+
+export function attrsStr (attrObj = {}, exclude = []) {
+  return Object.keys(attrObj)
+    .filter(attr => !exclude.includes(attr))
+    .map(attr => {
+      if (typeof attrObj[attr] !== 'string') {
+        return attr
+      }
+
+      const val = attrObj[attr].replace('"', '\'')
+
+      if (attr === 'hid') {
+        attr = 'data-hid'
+      }
+
+      return `${attr}="${val}"`
+    }).join(' ')

