+
+export function chainFn (base, fn) {
+  if (!(fn instanceof Function)) {
+    return
+  }
+  return function () {
+    if (base instanceof Function) {
+      base.apply(this, arguments)
+    }
+    fn.apply(this, arguments)
+  }
